function restoreSidebarState(){
  if(localStorage.getItem('atw_sb_hidden')==='1'){
    const layout=$('mainLayout');
    if(layout){layout.classList.add('sb-hidden');}
    const btn=$('sbToggleBtn');
    if(btn)btn.title='Tampilkan sidebar';
  }
}

// ── Tab skeleton helpers ────────────────────────────────────
function showTabSkeleton(tab){
  var el=document.getElementById('skel-'+tab);
  if(el) el.classList.remove('hidden');
}
function hideTabSkeleton(tab){
  var el=document.getElementById('skel-'+tab);
  if(el) el.classList.add('hidden');
}

function sw(t,el){
  activeTab=t;
  document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));
  el.classList.add('active');
  document.querySelectorAll('.tp').forEach(x=>x.classList.remove('active'));
  $('tp-'+t).classList.add('active');
  // Sync project selector sebelum render
  if(selId) _syncAllProjSelectors(selId);
  // Tampilkan skeleton saat tab baru dibuka (data mungkin belum ada)
  var SKEL_TABS=['wbs','daily','cost','issues','procurement','manpower'];
  if(SKEL_TABS.includes(t)) showTabSkeleton(t);
  if(t==='overview')renderOV();
  if(t==='projects')renderProjTab();
  if(t==='manpower'){renderMP();setTimeout(()=>{renderMpLog&&renderMpLog();hideTabSkeleton('manpower');},100);}
  if(t==='issues'){renderIssues();hideTabSkeleton('issues');}
  if(t==='procurement'){renderProc();hideTabSkeleton('procurement');}
  if(t==='wbs'){
    renderWBS();hideTabSkeleton('wbs');
  }
  if(t==='daily'){renderDailyReport();hideTabSkeleton('daily');}
  if(t==='cost'){
    const cfp=$('costFiltProj');if(cfp)cfp._costFiltManual=false;
    const rfp=$('rabFiltProj');if(rfp&&selId)rfp.value=selId;
    renderCost();renderRab();hideTabSkeleton('cost');
  }
  if(t==='scurve')renderSCurve();
}

