function exportExcel(){
  if(!P.length){toast('Tidak ada data','warn');return;}
  const wb=XLSX.utils.book_new();
  const toSheet=(data,cols)=>XLSX.utils.json_to_sheet(data.length?data:[{Info:'Empty'}]);
  // PROJECTS
  const ps=XLSX.utils.json_to_sheet(P.map(p=>({ID:p.id,Kode:p.kode,'Nama Project':p.nama,Lokasi:p.lokasi||'',Client:p.client||'','Tgl Mulai':p.mulai||'','Tgl Selesai':p.selesai||'',Status:p.status,'Plan (%)':p.plan,'Actual (%)':p.actual,'Variance (%)':p.actual-p.plan,SPI:p.plan>0?+(p.actual/p.plan).toFixed(2):0,'Mandays Plan':p.mdPlan||p.mpPlan||0,'MP Actual (workers)':p.mpActual||0,'MH Plan/hr':p.mhPlan||0,Weather:p.weather||'','Project Manager':p.picPm||'','Site Manager':p.picSm||'','Engineer':p.picEng||'','Procurement':p.picProc||'',Catatan:p.notes||''})));
  ps['!cols']=[{wch:14},{wch:10},{wch:28},{wch:20},{wch:20},{wch:12},{wch:12},{wch:12},{wch:8},{wch:8},{wch:10},{wch:6},{wch:8},{wch:8},{wch:8},{wch:18},{wch:28}];
  XLSX.utils.book_append_sheet(wb,ps,'PROJECTS');
  // HISTORY
  const hs=[];P.forEach(p=>(p.history||[]).forEach(h=>hs.push({ID_Project:p.id,Kode:p.kode,Tanggal:h.date,'Actual (%)':h.actual,'Plan (%)':h.plan,Manpower:h.mp||0,Keterangan:h.notes||''})));
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(hs.length?hs:[{Info:'No history'}]),'HISTORY');
  // ISSUES
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(ISS.length?ISS.map(i=>{const pr=P.find(p=>p.id===i.projId);return{ID:i.id,'ID Project':i.projId,'Kode Project':pr?.kode||'',Uraian:i.uraian,Tanggal:i.tgl||'',Kategori:i.kategori,Prioritas:i.prioritas,PIC:i.pj||'','Due Date':i.due||'',Tindakan:i.action||'',Status:i.status,'Tgl Selesai':i.done||''};}):[{Info:'No issues'}]),'ISSUES');
  // PROCUREMENT
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(PROC.length?PROC.map(i=>{const pr=P.find(p=>p.id===i.projId);return{ID:i.id,'ID Project':i.projId,'Kode Project':pr?.kode||'',Item:i.item,Kategori:i.kategori,Qty:i.qty||'',Satuan:i.satuan||'',Supplier:i.supplier||'','Due Date':i.due||'',Status:i.status,Catatan:i.notes||''};}):[{Info:'No procurement'}]),'PROCUREMENT');
  // MANPOWER LOG
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(MPLOGS.length?MPLOGS.map(m=>{const pr=P.find(p=>p.id===m.projId);return{ID:m.id,'ID Project':m.projId,'Kode Project':pr?.kode||'',Tanggal:m.date,SPV:m.spv||0,Mandor:m.mandor||0,Installer:m.installer||0,Tukang:m.tukang||0,Helper:m.helper||0,'Safety Man':m.safety||0,'Total Pekerja':m.total||0,'MH Actual':m.mhActual||0,'Time Lost (jam)':m.timeLost||0,'Alasan Time Lost':m.timeLostReason||'',Catatan:m.notes||''};}):[{Info:'No manpower logs'}]),'MANPOWER_LOG');
  // ACCIDENT LOG
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(ACCLOGS.length?ACCLOGS.map(a=>{const pr=P.find(p=>p.id===a.projId);return{ID:a.id,'ID Project':a.projId,'Kode Project':pr?.kode||'',Tanggal:a.date,Fatality:a.fatality||0,LTI:a.lti||0,'Minor Injury':a.minorInjury||0,'Med Treatment':a.medTreatment||0,'Property Damage':a.propertyDamage||0,Fire:a.fire||0,Traffic:a.traffic||0,Environment:a.environment||0,'Near Miss':a.nearMiss||0,'Time Lost (jam)':a.timeLost||0,Keterangan:a.notes||''};}):[{Info:'No accident logs'}]),'ACCIDENT_LOG');
  // META
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{App:'ATW Solar Dashboard',Version:'4.0',Exported:new Date().toLocaleString('id-ID'),Projects:P.length,Sig:'ATW_DASH_V4'}]),'_META');
  const fn=`ATW_Portfolio_${new Date().toISOString().slice(0,10)}.xlsx`;
  XLSX.writeFile(wb,fn);clean(fn);toast(`✓ Tersimpan: "${fn}"`);
}
