function readXL(file){
  const r=new FileReader();
  r.onload=e=>{
    try{
      const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array'});
      const meta=wb.Sheets['_META']?XLSX.utils.sheet_to_json(wb.Sheets['_META'])[0]:null;
      if(meta&&!['KWP_DASHBOARD_V2','KWP_DASHBOARD_V3','ATW_DASH_V4'].includes(meta.Sig)){toast('File tidak dikenali','error');return;}
      const rows=wb.Sheets['PROJECTS']?XLSX.utils.sheet_to_json(wb.Sheets['PROJECTS']):[];
      if(!rows.length){toast('Sheet PROJECTS kosong','warn');return;}
      const hist=wb.Sheets['HISTORY']?XLSX.utils.sheet_to_json(wb.Sheets['HISTORY']):[];
      const imp=rows.map(r=>({
        id:r['ID']||Date.now()+Math.random(),kode:r['Kode']||'',nama:r['Nama Project']||'',
        lokasi:r['Lokasi']||'',client:r['Client']||'',mulai:r['Tgl Mulai']||'',selesai:r['Tgl Selesai']||'',
        status:r['Status']||'Planning',plan:+r['Plan (%)']||0,actual:+r['Actual (%)']||0,
        mpPlan:+r['Mandays Plan']||+r['MP Plan']||0,mdPlan:+r['Mandays Plan']||+r['MP Plan']||0,mpActual:+r['MP Actual (workers)']||+r['MP Actual']||0,mhPlan:+r['MH Plan/hr']||+r['MH Plan']||0,
        weather:r['Weather']||'Partly Cloudy',notes:r['Catatan']||'',
        history:hist.filter(h=>h['ID_Project']==r['ID']).map(h=>({date:h['Tanggal'],actual:h['Actual (%)'],plan:h['Plan (%)'],mp:h['Manpower']||0,notes:h['Keterangan']||''}))
      }));
      const impI=wb.Sheets['ISSUES']?XLSX.utils.sheet_to_json(wb.Sheets['ISSUES']).filter(r=>r['Uraian']).map(r=>({id:r['ID']||Date.now()+Math.random(),projId:r['ID Project'],uraian:r['Uraian'],tgl:r['Tanggal']||'',kategori:r['Kategori']||'Other',prioritas:r['Prioritas']||'Medium',pj:r['PIC']||'',due:r['Due Date']||'',action:r['Tindakan']||'',status:r['Status']||'Open',done:r['Tgl Selesai']||''})):[];
      const impP=wb.Sheets['PROCUREMENT']?XLSX.utils.sheet_to_json(wb.Sheets['PROCUREMENT']).filter(r=>r['Item']).map(r=>({id:r['ID']||Date.now()+Math.random(),projId:r['ID Project'],item:r['Item'],kategori:r['Kategori']||'Material',qty:r['Qty']||'',satuan:r['Satuan']||'',supplier:r['Supplier']||'',due:r['Due Date']||'',status:r['Status']||'Waiting Approval',notes:r['Catatan']||''})):[];
      const impM=wb.Sheets['MANPOWER_LOG']?XLSX.utils.sheet_to_json(wb.Sheets['MANPOWER_LOG']).filter(r=>r['Tanggal']).map(r=>({id:r['ID']||Date.now()+Math.random(),projId:r['ID Project'],date:r['Tanggal'],spv:+r['SPV']||0,mandor:+r['Mandor']||0,installer:+r['Installer']||0,tukang:+r['Tukang']||0,helper:+r['Helper']||0,safety:+r['Safety Man']||0,total:+r['Total Pekerja']||0,mhActual:+r['MH Actual']||0,timeLost:+r['Time Lost (jam)']||0,timeLostReason:r['Alasan Time Lost']||'',notes:r['Catatan']||''})):[];
      const impA=wb.Sheets['ACCIDENT_LOG']?XLSX.utils.sheet_to_json(wb.Sheets['ACCIDENT_LOG']).filter(r=>r['Tanggal']).map(r=>({id:r['ID']||Date.now()+Math.random(),projId:r['ID Project'],date:r['Tanggal'],fatality:+r['Fatality']||0,lti:+r['LTI']||0,minorInjury:+r['Minor Injury']||0,medTreatment:+r['Med Treatment']||0,propertyDamage:+r['Property Damage']||0,fire:+r['Fire']||0,traffic:+r['Traffic']||0,environment:+r['Environment']||0,nearMiss:+r['Near Miss']||0,timeLost:+r['Time Lost (jam)']||0,notes:r['Keterangan']||''})):[];
      pendImp={P:imp,I:impI,PR:impP,M:impM,A:impA,fn:file.name};
      $('impInfo').textContent=`File: ${file.name} · ${imp.length} project · ${impI.length} issue · ${impP.length} proc · ${impM.length} manpower log`;
      $('impTbl').innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:11px"><tr style="background:var(--sf2)">${['Kode','Nama','Status','Actual','Plan'].map(h=>`<th style="padding:5px 7px;font-size:9px;text-transform:uppercase;color:var(--mt);text-align:left;border-bottom:1px solid var(--bd)">${h}</th>`).join('')}</tr>${imp.map(p=>`<tr><td style="padding:4px 7px;font-family:var(--fm);font-size:10px">${p.kode}</td><td style="padding:4px 7px">${p.nama}</td><td style="padding:4px 7px"><span class="pill p-${({'On Track':'on','Delayed':'del','Critical':'crit','Planning':'plan','Done':'done'})[p.status]||'plan'}">${p.status}</span></td><td style="padding:4px 7px;font-family:var(--fm);color:var(--gn)">${p.actual}%</td><td style="padding:4px 7px;font-family:var(--fm);color:var(--bl)">${p.plan}%</td></tr>`).join('')}</table>`;
      $('impPrev').style.display='block';$('btnConfImp').style.display='block';
      show('ov-import');
    }catch(err){toast('Gagal baca file: '+err.message,'error');}
  };
  r.readAsArrayBuffer(file);
}
