// ── AUTO-REFRESH EVERY 10 MIN (merged from patch3) ──────────────────────────

var _p3LastRefreshTs = 0;

function _p3UpdateLastRefreshIndicator() {
  var smsg = document.getElementById('smsg');
  if (!smsg || !_p3LastRefreshTs) return;
  var mins = Math.floor((Date.now() - _p3LastRefreshTs) / 60000);
  if (mins < 1) {
    smsg.textContent = 'Tersinkron baru saja';
  } else {
    smsg.textContent = 'Tersinkron ' + mins + ' menit lalu';
  }
}

// Update last-refresh indicator setiap menit
setInterval(function() {
  if (_p3LastRefreshTs) _p3UpdateLastRefreshIndicator();
}, 60000);

// Jangan auto-refresh kalau ada risiko MENIMPA editan yang belum tersimpan:
//  (1) ada operasi tertunda di antrian (atw_sq) — reload menimpa data lokal yang belum sync
//  (2) ada modal/form terbuka (.ov.open) — user sedang mengedit
//  (3) ada field input difokuskan — user sedang mengetik
// Mengembalikan alasan (string) jika TIDAK aman, atau null jika aman.
function _refreshUnsafe() {
  try {
    if (window._sbQueue && typeof window._sbQueue.list === 'function') {
      var q = window._sbQueue.list();
      if (q && q.length) return 'antrian-pending(' + q.length + ')';
    } else {
      var raw = localStorage.getItem('atw_sq');
      if (raw && raw !== '[]') return 'antrian-pending';
    }
    if (document.querySelector('.ov.open')) return 'modal-terbuka';
    var ae = document.activeElement;
    if (ae) {
      var tag = (ae.tagName || '').toUpperCase();
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || ae.isContentEditable) {
        return 'sedang-mengetik';
      }
    }
  } catch (e) {}
  return null;
}
window._refreshUnsafe = _refreshUnsafe;

// Auto-refresh data setiap 10 menit (saat online)
setInterval(function() {
  if (navigator.onLine && typeof loadFromSupabase === 'function') {
    var why = _refreshUnsafe();
    if (why) { console.log('[auto-refresh] dilewati —', why); return; }
    loadFromSupabase().then(function() {
      _p3LastRefreshTs = Date.now();
      _p3UpdateLastRefreshIndicator();
    }).catch(function(e) {
      console.warn('[auto-refresh]', e.message);
    });
  }
}, 10 * 60 * 1000);

// Visibility change: refresh saat user kembali ke tab

// ── OPTIMISTIC UI HELPER ─────────────────────────────────────
// Panggil sebelum await persist — update UI langsung
// rollback() dipanggil jika persist gagal
function _optimisticUpdate(renderFn, rollbackFn) {
  // Re-render segera (data di memory sudah diupdate oleh original fn)
  try { if(typeof renderFn === 'function') renderFn(); } catch(e) {}
  // Return rollback helper
  return function rollback(errorMsg) {
    if(typeof rollbackFn === 'function') rollbackFn();
    try { if(typeof renderFn === 'function') renderFn(); } catch(e) {}
    if(typeof toast === 'function') toast('Gagal simpan — perubahan dibatalkan','error');
    console.warn('[optimistic rollback]', errorMsg);
  };
}
window._optimisticUpdate = _optimisticUpdate;

document.addEventListener('visibilitychange', function() {
  if (document.visibilityState === 'visible' && navigator.onLine) {
    var stale = Date.now() - (_p3LastRefreshTs || 0) > 5 * 60 * 1000; // 5 min
    if (stale && typeof loadFromSupabase === 'function') {
      var why = _refreshUnsafe();
      if (why) { console.log('[auto-refresh tab] dilewati —', why); return; }
      loadFromSupabase().then(function() {
        _p3LastRefreshTs = Date.now();
        _p3UpdateLastRefreshIndicator();
      }).catch(function() {});
    }
  }
});


// ══════════════════════════════════════════════════════════════
//  LAZY LOADING — PROJECT-SCOPED DATA FETCH (merged from patch4)
//  Phase 1: projects+history+docs → render()
//  Phase 2: 8 secondary tables on-demand per-project
// ══════════════════════════════════════════════════════════════
window.addEventListener('load', function _initLazyLoad() {
  'use strict';
  // ── Helpers ────────────────────────────────────────────────
  function _sb()  { return (typeof _initSb === 'function') ? _initSb() : null; }
  function _log(m){ console.log('[Patch4]', m); }

  // ── State loading ──────────────────────────────────────────
  var _loaded   = new Set();  // projId sudah di-fetch
  var _loading  = new Set();  // projId sedang di-fetch
  var _lastSel  = null;       // deteksi perubahan selId

  // ── Merge helper: ganti slice projId di array ──────────────
  function _merge(arr, pid, newItems) {
    return arr
      .filter(function(x){ return String(x.projId) !== pid; })
      .concat(newItems);
  }

  // ── Refresh overview (infografis) ter-debounce ─────────────
  // Saat banyak proyek dimuat beruntun (fase 2 + background), kumpulkan jadi 1 render
  // ~250ms setelah load terakhir → data overview ikut terisi TANPA animasi restart berkali2.
  var _ovRefreshT = null;
  function _ovRefreshDebounced() {
    if (_ovRefreshT) clearTimeout(_ovRefreshT);
    _ovRefreshT = setTimeout(function(){
      _ovRefreshT = null;
      if (typeof renderOV === 'function') { try { renderOV(); } catch(e){} }
    }, 250);
  }

  // ── ANTI-PATAH: tahan paint overview selama bulk-load ──────────────────────
  // Sejak halaman dimuat sampai SELURUH proyek selesai dimuat, JANGAN paint #ovDash.
  // Tanpa ini, overview ter-render berkali-kali (cache→parsial→penuh) & animasi entrance
  // terpotong tiap proyek selesai → "patah-patah". Kita bungkus renderOV (global dari
  // projects.js) agar no-op selama _ovInitialBulk; #ovDash tetap skeleton. Setelah bulk
  // selesai, _ovFinalRender() memanggil sekali → satu animasi bersih dgn data lengkap.
  // Seluruh logika ini ada DI SATU FILE (core.js) agar tak bergantung versi projects.js.
  window._ovInitialBulk = true;   // aktif sejak page-load (mencakup render cache/Phase1)
  console.log('[ATW] core.js v13 dimuat — fix klik sidebar (delegasi capture) + anti-patah overview');
  if (typeof window.renderOV === 'function' && !window.__ovWrapped) {
    window.__ovWrapped = true;
    var _origRenderOV = window.renderOV;
    window.renderOV = function() {
      if (window._ovInitialBulk) return;   // diam selama bulk → skeleton bertahan
      return _origRenderOV.apply(this, arguments);
    };
  }

  // Picu animasi entrance overview secara kokoh — independen projects.js.
  function _ovInjectAnimCss() {
    if (document.getElementById('ovAnimCss')) return;
    var s = document.createElement('style');
    s.id = 'ovAnimCss';
    s.textContent =
      '@keyframes ovRise{from{opacity:0;transform:translateY(16px) scale(.985)}to{opacity:1;transform:none}}' +
      '#ovDash.ov-enter .ov-card{animation:ovRise .55s cubic-bezier(.22,1,.36,1) both}' +
      '#ovDash.ov-enter .ov-kstrip .ov-card:nth-child(2){animation-delay:.04s}' +
      '#ovDash.ov-enter .ov-kstrip .ov-card:nth-child(3){animation-delay:.08s}' +
      '#ovDash.ov-enter .ov-kstrip .ov-card:nth-child(4){animation-delay:.12s}' +
      '#ovDash.ov-enter .ov-kstrip .ov-card:nth-child(5){animation-delay:.16s}' +
      '#ovDash.ov-enter .ov-kstrip .ov-card:nth-child(6){animation-delay:.20s}' +
      '#ovDash.ov-enter .ov-r:nth-of-type(2) .ov-card{animation-delay:.16s}' +
      '#ovDash.ov-enter .ov-r:nth-of-type(3) .ov-card{animation-delay:.24s}' +
      '#ovDash.ov-enter .ov-r:nth-of-type(4) .ov-card{animation-delay:.32s}';
    document.head.appendChild(s);
  }

  function _ovPlayAnim() {
    _ovInjectAnimCss();
    requestAnimationFrame(function(){ requestAnimationFrame(function(){   // tunggu markup ter-paint
      var d = document.getElementById('ovDash');
      if (!d) { console.warn('[ATW] #ovDash tidak ada'); return; }
      // 1) Animasi entrance kartu (CSS) — DIJAMIN terlihat, tak bergantung markup SVG
      d.classList.remove('ov-enter'); void d.offsetWidth; d.classList.add('ov-enter');
      // 2) Animasi gauge/donut/angka (JS) — bila elemen & fungsi tersedia
      var arcs = d.querySelectorAll('.ov-arc').length,
          needles = d.querySelectorAll('.ov-needle').length,
          counts = d.querySelectorAll('.ov-count').length,
          hasSkel = !!d.querySelector('.ov-skel');
      console.log('[ATW] diag animasi → arc:'+arcs+' needle:'+needles+' count:'+counts+' skeleton-tersisa:'+hasSkel+' _ovAnimate:'+(typeof window._ovAnimate));
      if (typeof window._ovAnimate === 'function') {
        try { window._ovAnimate(d); } catch(e){ console.warn('[ATW] _ovAnimate error', e); }
      }
    });});
  }

  // ═══════════════════════════════════════════════════════════
  // PHASE 1 — ganti loadFromSupabase sepenuhnya
  // ═══════════════════════════════════════════════════════════
  var _phase1Promise = null;
  var _bulkActive = false;      // true selama load penuh (Phase1+2+background) berlangsung
  var _fullyLoadedAt = 0;       // timestamp load penuh terakhir

  window.loadFromSupabase = function() {
    if (_phase1Promise) {
      _log('Dedup: Phase 1 sedang berjalan');
      return _phase1Promise;
    }
    // Cegah RELOAD berulang saat login. autoLoadOnStart dipanggil 3x (checkSession/_loginSuccess/
    // returning-user) → tanpa guard ini tiap panggilan memuat ulang penuh & me-rebuild+animasi lagi,
    // sehingga animasi entrance siklus-1 ditimpa siklus-2 & 3 → "tidak ada motion".
    if (_bulkActive) { _log('Skip: bulk-load masih berjalan'); return Promise.resolve(); }
    if (_fullyLoadedAt && (Date.now() - _fullyLoadedAt) < 8000) {
      _log('Skip: data baru saja dimuat penuh — tak perlu reload (jaga animasi)');
      return Promise.resolve();
    }
    _bulkActive = true;
    window._ovInitialBulk = true;   // mulai bulk-load → tahan render overview sampai semua data masuk (anti patah)
    clearTimeout(window.__ovBulkFb);
    window.__ovBulkFb = setTimeout(function(){   // pengaman: jangan nyangkut skeleton bila bulk gagal/lambat
      if (window._ovInitialBulk) { try { _ovFinalRender(); } catch(e){} }
    }, 9000);
    _phase1Promise = _doPhase1().finally(function(){ _phase1Promise = null; });
    return _phase1Promise;
  };

  async function _doPhase1() {
    var client = _sb();
    if (!client) {
      if (typeof toast === 'function') toast('Supabase belum siap', 'error');
      return;
    }

    try {
      if (typeof toast === 'function') toast('Memuat data proyek...', 'info');
      _log('Phase 1: projects + history + documents...');
      var t0 = Date.now();

      var results = await Promise.all([
        client.from('projects').select('*').order('created_at'),
        client.from('project_history').select('*').order('date'),
        client.from('documents').select('*').order('created_at', { ascending: false }),
      ]);

      results.forEach(function(r, i){
        if (r.error) console.warn('[Phase1] query', i, r.error.message);
      });

      var projects  = results[0].data || [];
      var history   = results[1].data || [];
      var documents = results[2].data || [];

      // ── KRITIS: tulis ke let-binding, BUKAN window.X ──────
      // let P, ISS, ... di core.js BUKAN window.P, window.ISS
      // render() membaca P (let), bukan window.P
      P = projects.map(mapProject);

      // Seed timestamp deteksi konflik dari server → cek konflik bekerja pada alur load→edit→simpan
      if (typeof window.sbTrackTs === 'function') {
        projects.forEach(function(row){
          if (row && row.updated_at) window.sbTrackTs('projects', row.id, row.updated_at);
        });
      }

      // Reset array sekunder — data lama semua proyek dihapus
      ISS     = [];
      PROC    = [];
      MPLOGS  = [];
      ACCLOGS = [];
      COSTS   = [];
      RAB     = [];
      WBS     = [];
      SCURVE  = [];

      // Documents: tidak ada proj_id filter di query asli → global
      if (typeof mapDocument === 'function') {
        DOCS = documents.map(mapDocument);
      }

      // Merge history ke P
      history.forEach(function(h){
        var p = P.find(function(x){ return x.id === h.proj_id; });
        if (p) {
          p.history = p.history || [];
          p.history.push({
            date: h.date, actual: h.actual, plan: h.plan,
            mp: h.mp, notes: h.notes, status: h.status
          });
        }
      });

      // Reset cache
      _loaded.clear();
      _loading.clear();

      _log('Phase 1 selesai ' + (Date.now()-t0) + 'ms — ' + P.length + ' proyek');

      // Render overview sekarang (data sekunder menyusul)
      if (typeof render === 'function') render();
      if (typeof toast === 'function') toast('Proyek dimuat ✓');

      // Update timestamp indikator patch3
      window._p3LastRefreshTs = Date.now();
      if (typeof window._p3UpdateLastRefreshIndicator === 'function') {
        window._p3UpdateLastRefreshIndicator();
      }

      // Subscribe realtime
      if (typeof sbSubscribeRealtime === 'function') sbSubscribeRealtime();

      // Phase 2: proyek aktif dulu
      var activeId = (typeof selId !== 'undefined' && selId) ||
                     (P[0] && P[0].id) || null;
      if (activeId) {
        _log('Phase 2: proyek aktif ' + activeId);
        await window.loadProjectData(activeId);
      }

      // Background: sisa proyek
      _backgroundLoadAll();

    } catch(err) {
      if (typeof toast === 'function') toast('Gagal load: ' + err.message, 'error');
      console.error('[Phase1]', err);
    }
  }

  // ═══════════════════════════════════════════════════════════
  // PHASE 2 — data sekunder per-project
  // ═══════════════════════════════════════════════════════════
  window.loadProjectData = async function(projId) {
    if (!projId) return;
    var pid = String(projId);
    if (_loaded.has(pid))  { _log('cache hit: ' + pid); return; }
    if (_loading.has(pid)) { _log('in-flight: ' + pid); return; }

    var client = _sb();
    if (!client) return;

    _loading.add(pid);
    var t0 = Date.now();
    _log('loadProjectData(' + pid + ')...');

    try {
      var res = await Promise.all([
        client.from('issues').select('*')
              .eq('proj_id', pid).order('created_at', { ascending: false }),
        client.from('procurement').select('*')
              .eq('proj_id', pid).order('created_at', { ascending: false }),
        client.from('manpower_logs').select('*')
              .eq('proj_id', pid).order('date', { ascending: false }),
        client.from('accident_logs').select('*')
              .eq('proj_id', pid).order('date', { ascending: false }),
        client.from('costs').select('*')
              .eq('proj_id', pid).eq('_deleted', false)
              .order('date', { ascending: false }),
        client.from('rab').select('*')
              .eq('proj_id', pid).order('urutan'),
        client.from('wbs').select('*')
              .eq('proj_id', pid).order('order'),
        client.from('scurve').select('*')
              .eq('proj_id', pid).order('week'),
      ]);

      res.forEach(function(r, i){
        if (r.error) console.warn('[loadProjectData] q' + i + ':', r.error.message);
      });

      // ── KRITIS: assign ke let-binding, BUKAN window.X ─────
      ISS     = _merge(ISS,     pid, (res[0].data || []).map(mapIssue));
      PROC    = _merge(PROC,    pid, (res[1].data || []).map(mapProcurement));
      MPLOGS  = _merge(MPLOGS,  pid, (res[2].data || []).map(mapManpower));
      ACCLOGS = _merge(ACCLOGS, pid, (res[3].data || []).map(mapAccident));
      COSTS   = _merge(COSTS,   pid, (res[4].data || []).map(mapCost));
      RAB     = _merge(RAB,     pid, (res[5].data || []).map(mapRab));
      WBS     = _merge(WBS,     pid, (res[6].data || []).map(mapWbs));
      SCURVE  = _merge(SCURVE,  pid, (res[7].data || []).map(mapScurve));

      // Seed timestamp deteksi konflik untuk semua record sekunder yang baru di-load
      if (typeof window.sbTrackTs === 'function') {
        [['issues',0],['procurement',1],['manpower_logs',2],['accident_logs',3],
         ['costs',4],['rab',5],['wbs',6],['scurve',7]].forEach(function(pair){
          (res[pair[1]].data || []).forEach(function(row){
            if (row && row.updated_at) window.sbTrackTs(pair[0], row.id, row.updated_at);
          });
        });
      }


      _loaded.add(pid);
      _loading.delete(pid);
      _log('loadProjectData(' + pid + ') OK ' + (Date.now()-t0) + 'ms' +
           ' | WBS:' + WBS.filter(function(w){ return String(w.projId)===pid; }).length);

      // Re-render penuh utk proyek aktif; selain itu refresh komponen yang menampilkan
      // Plan lintas-proyek (sidebar + kartu status tab aktif), karena nilai Plan tiap
      // proyek baru benar setelah SCURVE-nya selesai dimuat.
      window._ovReady = true;   // data sekunder proyek sudah mulai masuk → overview boleh paint data nyata
      var curSel = (typeof selId !== 'undefined') ? String(selId) : null;
      if (window._ovInitialBulk) {
        // Bulk-load awal (login): JANGAN render overview tiap proyek — itu yang bikin infografis
        // di-rebuild di tengah animasi → motion patah. Cukup perbarui sidebar; overview dirender
        // SEKALI di akhir _backgroundLoadAll (satu animasi bersih, data sudah lengkap).
        if (typeof renderSB === 'function') { try { renderSB(); } catch(e){} }
      } else {
        // Load on-demand (mis. buka proyek setelah login): segarkan seperti biasa, ter-debounce.
        if (curSel === pid && typeof render === 'function') { render(); }
        else if (typeof renderSB === 'function') { renderSB(); }
        if (typeof activeTab !== 'undefined') {
          if (activeTab === 'overview') { _ovRefreshDebounced(); }
          else if (activeTab === 'projects' && typeof renderProjTab === 'function') { try { renderProjTab(); } catch(e){} }
        }
      }

    } catch(err) {
      _loading.delete(pid);
      console.warn('[loadProjectData]', pid, err.message);
    }
  };

  // ═══════════════════════════════════════════════════════════
  // BACKGROUND — sisa proyek, stagger 400ms
  // ═══════════════════════════════════════════════════════════
  function _wait(ms){ return new Promise(function(r){ setTimeout(r, ms); }); }

  // Render overview SEKALI setelah seluruh bulk-load selesai → satu animasi entrance bersih,
  // data sudah lengkap, tanpa rebuild di tengah animasi.
  function _ovFinalRender() {
    clearTimeout(window.__ovBulkFb);
    _bulkActive = false;
    _fullyLoadedAt = Date.now();
    if (!window._ovInitialBulk) return;   // idempotent: hanya jalan sekali per siklus load
    window._ovInitialBulk = false;
    window._ovReady = true;
    console.log('[ATW] v12 — render final + animasi entrance ✓ (activeTab=' + (typeof activeTab!=='undefined'?activeTab:'?') + ')');
    if (typeof render === 'function') { try { render(); } catch(e){} }
    if (typeof activeTab === 'undefined' || activeTab === 'overview') { _ovPlayAnim(); }
  }

  async function _backgroundLoadAll() {
    if (!Array.isArray(P) || !P.length) { _ovFinalRender(); return; }
    var remaining = P.filter(function(p){
      var pid = String(p.id);
      return !_loaded.has(pid) && !_loading.has(pid);
    });
    if (!remaining.length) { _ovFinalRender(); return; }
    _log('Background: ' + remaining.length + ' proyek tersisa');
    for (var i = 0; i < remaining.length; i++) {
      await _wait(400);
      await window.loadProjectData(remaining[i].id);
    }
    _log('Background selesai — semua ' + P.length + ' proyek loaded ✓');
    _ovFinalRender();
  }

  // ═══════════════════════════════════════════════════════════
  // AUTO-TRIGGER — deteksi selId berubah lewat render()
  // ═══════════════════════════════════════════════════════════
  var _origRender = window.render;
  if (typeof _origRender === 'function') {
    window.render = function() {
      _origRender.apply(this, arguments);
      var cur = (typeof selId !== 'undefined' && selId) ? String(selId) : null;
      if (cur && cur !== _lastSel) {
        _lastSel = cur;
        if (!_loaded.has(cur) && !_loading.has(cur)) {
          _log('render(): selId→' + cur + ' belum di-cache, trigger load');
          window.loadProjectData(cur);
        }
      }
    };
    _log('render() wrapper terpasang ✓');
  }

  // ═══════════════════════════════════════════════════════════
  // DEBUG API
  // ═══════════════════════════════════════════════════════════
  window._p4 = {
    status: function() {
      // Baca P langsung (let binding, bukan window.P)
      if (!Array.isArray(P) || !P.length) { console.log('P kosong'); return; }
      console.table(P.map(function(p){
        var pid = String(p.id);
        return {
          id:     pid.slice(-6),
          nama:   (p.nama||'').slice(0,20),
          status: _loading.has(pid) ? '⏳ loading' : _loaded.has(pid) ? '✓ loaded' : '⋯ pending'
        };
      }));
      console.log('WBS total:', WBS.length, '| ISS:', ISS.length, '| COSTS:', COSTS.length);
    },
    reload: function(projId){
      var pid = String(projId);
      _loaded.delete(pid); _loading.delete(pid);
      return window.loadProjectData(pid);
    },
    reloadAll: function(){ return window.loadFromSupabase(); },
    loaded:  _loaded,
    loading: _loading,
  };

  _log([
    'Patch 4 v2 loaded ✓ (fix: let-binding, bukan window.X)',
    '  • Phase 1: projects+history+docs → render()',
    '  • Phase 2: 8 tabel sekunder on-demand per-project',
    '  • Background: sisa proyek stagger 400ms',
    '  • Debug: window._p4.status()',
  ].join('\n'));
});

